css:
.turismo-sim-container {
    padding: 28px;
    background: linear-gradient(170deg, #0b1e33 0%, #12314f 40%, #0e3b2d 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8ece6;
}

.turismo-sim-header {
    background: linear-gradient(135deg, rgba(0,166,81,0.2), rgba(255,205,0,0.12));
    border: 1px solid rgba(0,166,81,0.3);
    border-radius: 20px;
    padding: 32px 36px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.turismo-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #00a651, #ffcd00, #ce1126);
}
.turismo-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    color: #ffffff;
    margin: 0 0 6px 0;
    letter-spacing: 0.02em;
}
.turismo-sim-subtitle {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.65);
    margin: 0;
}
.turismo-sim-period-badge {
    background: rgba(0,166,81,0.2);
    border: 1px solid rgba(0,166,81,0.4);
    border-radius: 14px;
    padding: 12px 22px;
    text-align: center;
    font-size: 0.85rem;
    color: #a8e6cf;
    white-space: nowrap;
}
.turismo-sim-period-badge span:nth-child(2),
.turismo-sim-period-badge span:nth-child(4) {
    font-size: 1.6rem;
    font-weight: 700;
    color: #00e676;
    margin: 0 4px;
}

.turismo-sim-briefing {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,205,0,0.2);
    border-left: 4px solid #ffcd00;
    border-radius: 14px;
    padding: 26px 30px;
    margin-bottom: 24px;
}
.turismo-sim-briefing-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}
.turismo-sim-briefing-tag {
    background: rgba(255,205,0,0.15);
    color: #ffcd00;
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.turismo-sim-briefing-duration {
    color: rgba(255,255,255,0.45);
    font-size: 0.8rem;
}
.turismo-sim-briefing h2 {
    font-size: 1.15rem;
    color: #ffffff;
    margin: 0 0 10px 0;
    font-weight: 600;
}
.turismo-sim-briefing p {
    color: rgba(255,255,255,0.75);
    font-size: 0.92rem;
    line-height: 1.65;
    margin: 0;
}

.turismo-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.turismo-sim-kpi-card {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, background 0.2s ease;
}
.turismo-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.08);
}
.turismo-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
}
.turismo-sim-kpi-cash::before { background: #00e676; }
.turismo-sim-kpi-revenue::before { background: #ffcd00; }
.turismo-sim-kpi-community::before { background: #42a5f5; }
.turismo-sim-kpi-sustainability::before { background: #66bb6a; }
.turismo-sim-kpi-gdp::before { background: #ce1126; }
.turismo-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(255,255,255,0.5);
    margin-bottom: 8px;
}
.turismo-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
}
.turismo-sim-kpi-cash .turismo-sim-kpi-value { color: #00e676; }
.turismo-sim-kpi-revenue .turismo-sim-kpi-value { color: #ffcd00; }
.turismo-sim-kpi-community .turismo-sim-kpi-value { color: #42a5f5; }
.turismo-sim-kpi-sustainability .turismo-sim-kpi-value { color: #66bb6a; }
.turismo-sim-kpi-gdp .turismo-sim-kpi-value { color: #ef9a9a; }

.turismo-sim-controls {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 14px;
    padding: 28px;
    margin-bottom: 24px;
}
.turismo-sim-controls h3 {
    color: #ffffff;
    font-size: 1.05rem;
    margin: 0 0 20px 0;
    font-weight: 600;
}
.turismo-sim-control-group {
    margin-bottom: 18px;
}
.turismo-sim-control-group label {
    display: block;
    font-size: 0.82rem;
    color: rgba(255,255,255,0.65);
    margin-bottom: 6px;
    font-weight: 500;
}
.turismo-sim-controls input[type="number"],
.turismo-sim-controls select {
    background: rgba(0,0,0,0.3);
    border: 1px solid rgba(255,255,255,0.18);
    color: #e8ece6;
    border-radius: 8px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease;
}
.turismo-sim-controls input[type="number"]:focus,
.turismo-sim-controls select:focus {
    border-color: #00a651;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,166,81,0.2);
}
.turismo-sim-controls select option {
    background: #12314f;
    color: #e8ece6;
}
.turismo-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 22px;
}
.turismo-sim-submit-btn {
    background: linear-gradient(135deg, #00a651, #00c853);
    border: none;
    color: #ffffff;
    font-weight: 600;
    padding: 12px 32px;
    border-radius: 10px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.turismo-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0,166,81,0.3);
}
.turismo-sim-undo-btn {
    border-color: rgba(255,255,255,0.25);
    color: rgba(255,255,255,0.55);
    border-radius: 8px;
    padding: 8px 18px;
    font-size: 0.82rem;
}

.turismo-sim-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 24px;
}
.turismo-sim-chart-box {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px;
    min-height: 260px;
    position: relative;
}

.turismo-sim-history {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px;
    overflow-x: auto;
}
.turismo-sim-container .table {
    color: #e8ece6;
    margin: 0;
}
.turismo-sim-container .table thead th {
    border-color: rgba(255,255,255,0.15);
    color: rgba(255,255,255,0.6);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.turismo-sim-container .table td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
    vertical-align: middle;
}

@media (max-width: 768px) {
    .turismo-sim-container { padding: 16px; }
    .turismo-sim-header { flex-direction: column; gap: 16px; text-align: center; padding: 24px 20px; }
    .turismo-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .turismo-sim-charts-row { grid-template-columns: 1fr; }
    .turismo-sim-btn-row { flex-direction: column; }
    .turismo-sim-submit-btn { width: 100%; }
}
/* v1.1.0 end-of-game debrief panel */
.turismo-sim-results{background:rgba(255,255,255,0.04);border:1px solid rgba(255,205,0,0.55);border-left:4px solid #ffcd00;border-radius:12px;padding:16px 20px;margin:16px 0;}
.turismo-sim-results h3{margin:0 0 12px;color:#ffcd00;}
.turismo-results-grid{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:10px;}
.turismo-result-metric{flex:1 1 130px;background:rgba(0,0,0,0.25);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;}
.turismo-result-metric .tr-label{font-size:12px;color:#aaa;text-transform:uppercase;letter-spacing:.03em;}
.turismo-result-metric .tr-value{font-size:20px;font-weight:700;color:#fff;}
.turismo-insights-title{margin:10px 0 4px;color:#ddd;}
.turismo-insights{margin:0;padding-left:18px;}
.turismo-insights li{margin-bottom:6px;line-height:1.4;color:#ccc;}

