        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var totalNet = 0;
            var totalVisitors = 0;
            var i;
            for (i = 0; i < history.length; i++) {
                totalNet += (history[i].results ? history[i].results.netRevenue : 0) || 0;
                totalVisitors += (history[i].results ? history[i].results.visitors : 0) || 0;
            }
            var lastRound = history[history.length - 1].results || {};
            var finalCommunity = lastRound.communityIndex || 0;
            var finalSustain = lastRound.sustainabilityScore || 0;
            var finalGdp = lastRound.gdpImpact || 0;

            var composite = (finalCommunity * 0.3) + (finalSustain * 0.3) + Math.min(finalGdp * 10, 20) + (totalNet > 0 ? 20 : 0);

            var performance = T('perf_beginner');
            if (composite > 40) performance = T('perf_competent');
            if (composite > 60) performance = T('perf_advanced');
            if (composite > 80) performance = T('perf_excellent');

            var insights = [];
            if (finalCommunity > 60) {
                insights.push(T('insight_community_good'));
            } else {
                insights.push(T('insight_community_weak'));
            }
            if (finalSustain > 65) {
                insights.push(T('insight_sustain_good'));
            } else {
                insights.push(T('insight_sustain_weak'));
            }
            if (totalNet < 0) {
                insights.push(T('insight_loss'));
            }

            return {
                totalNetRevenue: totalNet,
                totalVisitors: totalVisitors,
                finalCommunityIndex: finalCommunity,
                finalSustainabilityScore: finalSustain,
                finalGdpImpact: finalGdp,
                composite: Math.round(composite),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.overCapacity) return window.mySimulation.t('hint_overcapacity');
            if (results.netRevenue < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.communityIndex < 25) return window.mySimulation.t('hint_low_community');
            if (state.domainState.sustainabilityScore < 30) return window.mySimulation.t('hint_low_sustainability');
            if (results.netRevenue > 0 && state.domainState.communityIndex > 50 && state.domainState.sustainabilityScore > 50) {
                return window.mySimulation.t('hint_balanced');
            }
            return null;
        }

